	/*
     * @param	event CreateMeasureEvent
     */
    @EventHandler( payloadType=CreateMeasureEvent.class )
    public void handle( CreateMeasureEvent event) {
	    LOGGER.info("handling CreateMeasureEvent - " + event );
	    Measure entity = new Measure();
            entity.setMeasureId( event.getMeasureId() );
            entity.setName( event.getName() );
            entity.setFormat( event.getFormat() );
            entity.setAggregation( event.getAggregation() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMeasure( entity );
    }

    /*
     * @param	event UpdateMeasureEvent
     */
    @EventHandler( payloadType=UpdateMeasureEvent.class )
    public void handle( UpdateMeasureEvent event) {
    	LOGGER.info("handling UpdateMeasureEvent - " + event );
    	
	    Measure entity = new Measure();
            entity.setMeasureId( event.getMeasureId() );
            entity.setName( event.getName() );
            entity.setFormat( event.getFormat() );
            entity.setSemanticModel( event.getSemanticModel() );
            entity.setDatasets( event.getDatasets() );
            entity.setGlossaryTerms( event.getGlossaryTerms() );
            entity.setAggregation( event.getAggregation() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindMeasure( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMeasure( entity );        
    }
    
