    /**
     * Method to retrieve the Measure via an MeasurePrimaryKey.
     * @param 	id Long
     * @return 	Measure
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Measure handle( FindMeasureQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getMeasureId() );
    }
    
    /**
     * Method to retrieve a collection of all Measures
     *
     * @param	query	FindAllMeasureQuery 
     * @return 	List<Measure> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Measure> handle( FindAllMeasureQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindMeasure,
 * but only if the id matches
 *
 * @param		entity	Measure
 */
	protected void emitFindMeasure( Measure entity ) {
		LOGGER.info("handling emitFindMeasure" );
		
	    queryUpdateEmitter.emit(FindMeasureQuery.class,
	                            query -> query.getFilter().getMeasureId().equals(entity.getMeasureId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllMeasure
	 * 
	 * @param		entity	Measure
	 */
	protected void emitFindAllMeasure( Measure entity ) {
		LOGGER.info("handling emitFindAllMeasure" );
		
	    queryUpdateEmitter.emit(FindAllMeasureQuery.class,
	                            query -> true,
	                            entity);
	}

